mapper.select:
SELECT TNA.*,STAFF.REALNAME,ORG.ORGNAME FROM TBL_NBSJ_RISK TNA LEFT JOIN TBL_STAFF STAFF ON STAFF.STAFFID = TNA.CREATEORID LEFT JOIN TBL_ORGANIZATION ORG ON ORG.ORGID = TNA.ORGID
1=1
AND ORG.ORGID = #{tblNbkzRiskVo.orgid}
AND TNA.RISKNAME like concat(concat('%',#{tblNbkzRiskVo.riskname}),'%')
AND TNA.RISKNUMBER like concat(concat('%',#{tblNbkzRiskVo.risknumber}),'%')
AND to_char(TNA.DISCOVEREDDATE,'yyyy-mm-dd') >= #{tblNbkzRiskVo.startDate}
AND to_char(TNA.DISCOVEREDDATE,'yyyy-mm-dd') <= #{tblNbkzRiskVo.endDate}
ORDER BY TNA.RISKID DESC
